    var g = data.readUInt8(3);
    var b = data.readUInt8(4);

    this.blink1.fadeToRGB(fadeMillis, r, g, b, function() {
      if (this.updateValueCallback) {
        this.updateValueCallback(Buffer.from([r, g, b]));
      }
    }.bind(this));

    callback(this.RESULT_SUCCESS);
  }
};

